public static List<BOM_D> getChildren(List<BOM_D> beanList,String parentId){
 //创建返回树结构数据集合
 List<BOM_D> treeList = new ArrayList<>();
 for (BOM_D bean : beanList) {
 //创建当前节点的bean
 BOM_D treeBean = new BOM_D();
 //创建当前节点下子节点的数据集合
 List<BOM_D> childrenList = new ArrayList<>();
 //如果当前节点等于【参数】父节点，则进行递归操作
 if (parentId.equals(bean.getPnote())){
 //将节点数据复制到当前bean下，也就是上面创建的【treeBean对象】
 BeanUtils.copyProperties(bean,treeBean);
 //递归查询当前节点是否有子节点
 childrenList = getChildren(beanList,bean.getItemMaster());
 //有则将子节点的数据集合添加到当前bean下,无节点则打上标识
 if (childrenList.size()>0){
 treeBean.setD(childrenList);
 treeBean.setIsLeaf(true);
 }else {
 treeBean.setIsLeaf(false);
 }
 //将当前构建的树对象放入返回集合中
 treeList.add(treeBean);
 }
 }
 return treeList;
}

