var divNum = 1;
switch (diffType) {
case "second":
 divNum = 1000;
 break;
case "minute":
 divNum = 1000 * 60;
 break;
case "hour":
 divNum = 1000 * 3600;
 break;
case "day":
 divNum = 1000 * 3600 * 24;
 break;
default:
 break;
}
return parseInt((eTime.getTime() - sTime.getTime()) / parseInt(divNum));

