器械客户收货入库时，同一个商品，同一个批号不同批次，需要按商品ID和输入第一个批号自动生成之后的顺序排列批号。 器械客户收货入库时，同一个商品，同一个批号不同批次，需要按商品ID和输入第一个批号自动生成之后的顺序排列批号。 收货验收员需要批号根据输入的第一个批次号批量自动生成后续批次功能。 通过正则表单式取输入批号字符后端数字，顺序+1后还原截取长度再拼接前段生成新的批次号：
function uf_auto(){
 var str = "";
 var row = ds_ddmx.recno ;
 for(var i = row ; i<ds_ddmx.recordCount-1;i++){
 str = ds_ddmx.getValueAt(i,"batchcode");

 if(str==""){
 form.alert("请对应品种第一行填写初始批号！！！！");
 return false;
 }

 if(ds_ddmx.getValueAt(i,"goodscode") != ds_ddmx.getValueAt(i+1,"goodscode") ){
 // alert(ds_ddmx.getValueAt(i,"goodscode") +",,,"+ds_ddmx.getValueAt(i+1,"goodscode") );
 form.alert("已到同品种最后一条！！！");
 return false;
 }

 var len = 0;
 var regex = /\d+$/; // 定义正则表达式，匹配字符串后连续的数字
 var result = str.match(/\d+$/)[0];
 len = result.length;
 result = parseInt(result)+1;
 result = "0000000000"+result.toString();//填充字符用以还原为之前截取下来的长度
 result = result.substring(result.length - len);

 var ph = str.substr(0,str.length-len);//取截取后的遗留字符串

 if(ph != null){
 ds_ddmx.setValueAt(i+1,"batchcode",ph+result);//拼接
 }else {
 ds_ddmx.setValueAt(i+1,"batchcode",result);
 }
 }
} 批号排序  JavaScript 时空 时空智友 供应链管理系统 实施问题

